#include "runtime.hpp"
#include "device.cuh"
#include "matmul.cuh"
#include <cstdio>
#include <cstring>
#include <vector>
using namespace halo6000;
__device__ uint8_t original_code(MatrixView w,int row,int col){const auto*base=static_cast<const uint8_t*>(w.data);if(w.format==WeightFormat::Q8Grouped128)return base[size_t(row)*(w.k/128)*136+(col/128)*136+col%128];size_t b=size_t(row)*(w.k/128)+col/128;auto*p=reinterpret_cast<const uint32_t*>(base+(b/16)*544+(b%16)*32);int t=col%16;unsigned code=(p[(col%128)/16]>>(4*(t%8)+t/8))&5;return code==5?255:code==1?1:0;}
__device__ uint16_t original_scale(MatrixView w,int row,int g){auto*base=static_cast<const uint8_t*>(w.data);if(w.format==WeightFormat::Q8Grouped128)return *reinterpret_cast<const uint16_t*>(base+size_t(row)*(w.k/128)*136+(g/4)*136+128+(g%4)*2);size_t b=size_t(row)*(w.k/128)+g;return *reinterpret_cast<const uint16_t*>(base+(b/16)*544+512+(b%16)*2);}
__global__ void certificate(PreparedMatmulView p,unsigned long long*errors){const auto w=p.source;uint64_t units=uint64_t(w.n/16)*(w.k/32)*32;for(uint64_t id=uint64_t(blockIdx.x)*blockDim.x+threadIdx.x;id<units;id+=uint64_t(gridDim.x)*blockDim.x){uint64_t tile=id/32;int lane=id%32,rt=tile/(w.k/32),g=tile%(w.k/32);uint32_t pane=0;for(int j=0;j<4;j++){int row=rt*16+lane/4+(j%2?8:0),col=g*32+(lane%4)*4+(j>=2?16:0);uint32_t word=0;for(int z=0;z<4;z++){uint8_t v=original_code(w,row,col+z);word|=uint32_t(v)<<(8*z);if(w.format==WeightFormat::Pane2){int e=j*4+z;pane|=uint32_t(v==255?5:v==1?1:0)<<(4*(e%8)+e/8);}}if(w.format==WeightFormat::Q8Grouped128&&word!=p.operands[id*4+j])atomicAdd(errors,1ull);}if(w.format==WeightFormat::Pane2&&pane!=p.operands[id])atomicAdd(errors,1ull);}
 int groups=w.k/(w.format==WeightFormat::Pane2?128:32);for(uint64_t id=uint64_t(blockIdx.x)*blockDim.x+threadIdx.x;id<uint64_t(w.n)*groups;id+=uint64_t(gridDim.x)*blockDim.x)if(p.weight_scales[id]!=original_scale(w,id/groups,id%groups))atomicAdd(errors,1ull);
}
__global__ void fill_quant(float*x,ActivationBuffer a){for(int i=blockIdx.x*blockDim.x+threadIdx.x;i<a.k;i+=gridDim.x*blockDim.x)x[i]=sinf(i*.071f)*(.1f+(i%53)*.017f);__syncthreads();}
__global__ void quant(const float*x,ActivationBuffer a){quantize_phase(x,a);}
__global__ void native(MatrixView w,ActivationView a,float*out){for(int row=blockIdx.x*(blockDim.x/32)+threadIdx.x/32;row<w.n;row+=gridDim.x*(blockDim.x/32)){float v=quantized_row(w,a,row);if(!(threadIdx.x&31))out[row]=v;}}
__global__ void compare(const float*a,const float*b,int n,unsigned long long*errors){for(int i=blockIdx.x*blockDim.x+threadIdx.x;i<n;i+=gridDim.x*blockDim.x)if(__float_as_uint(a[i])!=__float_as_uint(b[i]))atomicAdd(errors,1ull);}
static bool ok(Status s){if(s.ok())return true;fprintf(stderr,"%s\n",s.error().message.c_str());return false;}
template<WeightFormat F>static void launch(PreparedMatmulView w,PreparedActivationView a,float*out,cudaStream_t stream){if(w.source.k==512)matmul_q8_s1<F,4><<<w.source.n/16,256,0,stream>>>(w,a,out);else if(w.source.k==2048)matmul_q8_s1<F,16><<<w.source.n/16,256,0,stream>>>(w,a,out);else matmul_q8_s1<F,32><<<w.source.n/16,256,0,stream>>>(w,a,out);}
int main(int argc,char**argv){if(argc!=3)return 2;auto image=load_cached(argv[1],argv[2]);if(!image.ok())return 2;auto made=DeviceModel::create(image.value(),1,128);if(!made.ok())return 2;auto m=std::move(made.value());cudaStream_t stream;if(cudaStreamCreateWithFlags(&stream,cudaStreamNonBlocking)!=cudaSuccess)return 2;if(!ok(m->prepare_matmul(false,stream)))return 2;size_t bytes=m->prepared_bytes;if(!ok(m->prepare_matmul(false,stream))||bytes!=m->prepared_bytes||m->prepare_matmul(true,stream).ok())return 3;auto scratch=Workspace::create(128);if(!scratch.ok())return 2;auto w=std::move(scratch.value());float*reference=nullptr,*output=nullptr,*x=nullptr;unsigned long long*errors=nullptr;cudaMalloc(&reference,Vocab*4);cudaMalloc(&output,Vocab*4);cudaMalloc(&x,Inner*4);cudaMalloc(&errors,8);cudaMemsetAsync(errors,0,8,stream);
 std::vector<PreparedMatmulView>views{m->prepared.head};for(auto&p:m->prepared.layer){for(auto*v:{&p.qkv,&p.z,&p.alpha,&p.beta,&p.output,&p.q,&p.k,&p.v,&p.shared_gate,&p.shared_up,&p.shared_down})if(v->operands)views.push_back(*v);if(p.expert_gate.operands||p.expert_up.operands||p.expert_down.operands)return 4;}
 uint64_t values=0,outputs=0;for(auto p:views){if(!p.operands||p.operand_layout!=WeightOperandLayout::K32S8||p.source.experts!=1)return 4;certificate<<<1024,256,0,stream>>>(p,errors);values+=uint64_t(p.source.n)*p.source.k;PreparedActivationView a=p.source.k==4096?w->view.inner_mma:p.source.k==2048?w->view.hidden_mma:w->view.expert_mma;ActivationBuffer q=p.source.k==4096?w->view.inner_q:p.source.k==2048?w->view.hidden_q:w->view.expert_q;q.rows=1;a.input_experts=1;a.source=q.view();fill_quant<<<16,256,0,stream>>>(x,q);quant<<<16,256,0,stream>>>(x,q);prepare_matmul_activations<<<16,256,0,stream>>>(a,const_cast<uint32_t*>(a.operands));native<<<188,256,0,stream>>>(p.source,a.source,reference);if(p.source.format==WeightFormat::Pane2)launch<WeightFormat::Pane2>(p,a,output,stream);else launch<WeightFormat::Q8Grouped128>(p,a,output,stream);compare<<<188,256,0,stream>>>(reference,output,p.source.n,errors);outputs+=p.source.n;}
 unsigned long long count=0;cudaMemcpyAsync(&count,errors,8,cudaMemcpyDeviceToHost,stream);if(!ok(cuda_status(cudaStreamSynchronize(stream),"prepared runtime proof")))return 5;
 PreparedModel back{};if(!ok(cuda_status(cudaMemcpy(&back,m->weights.prepared,sizeof back,cudaMemcpyDeviceToHost),"prepared descriptor"))||memcmp(&back,&m->prepared,sizeof back))return 6;
 printf("{\"model\":\"%s\",\"prepared_bytes\":%zu,\"matrices\":%zu,\"original_values\":%llu,\"full_output_bits\":%llu,\"errors\":%llu,\"descriptor_roundtrip\":true,\"idempotent_scope\":true}\n",argv[1],bytes,views.size(),(unsigned long long)values,(unsigned long long)outputs,count);
 cudaFree(reference);cudaFree(output);cudaFree(x);cudaFree(errors);cudaStreamDestroy(stream);return count?1:0;
}
